def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda x: sum(row.count(x) for row in grid))

    # Find repeated full-width or full-height separator lines.
    for axis in (0, 1):
        length = h if axis == 0 else w
        span = w if axis == 0 else h

        separators = []
        for pos in range(length):
            line = ([grid[pos][j] for j in range(span)] if axis == 0
                    else [grid[j][pos] for j in range(span)])
            if line[0] != bg and all(x == line[0] for x in line):
                separators.append(pos)

        if not separators:
            continue

        period = (separators[1] - separators[0]
                  if len(separators) > 1 else separators[0] + 1)
        if period <= 0:
            continue

        # Collect the visible pattern at each position within the period,
        # then repeat it along the separator axis.
        pattern = {}
        for r in range(h):
            for c in range(w):
                phase = (r % period) if axis == 0 else (c % period)
                key = (phase, c) if axis == 0 else (r, phase)
                if grid[r][c] != bg:
                    pattern.setdefault(key, grid[r][c])

        out = [row[:] for row in grid]
        for r in range(h):
            for c in range(w):
                phase = (r % period) if axis == 0 else (c % period)
                key = (phase, c) if axis == 0 else (r, phase)
                if out[r][c] == bg and key in pattern:
                    out[r][c] = pattern[key]
        return out

    return [row[:] for row in grid]
